func DispatchNeuroChain(d, p, m byte, vec *CognitiveChainVector) error {
	identity, err := ResolveNeuroChainIdentity(d, p, m)
	if err != nil {
		return err
	}
	handler := NeuroChainTable[identity.Code]
	if handler == nil {
		return errors.New("neuro chain kernel not initialized")
	}
	return handler(identity, vec)
}

func GetNeuroChainExecutionCount(code uint16) uint64 {
	if code >= 1000 {
		return 0
	}
	return atomic.LoadUint64(&NeuroChainMetrics[code])
}
